import{_ as a,a0 as d,w as r,s,I as e,x as i,a1 as n,A as o,ao as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const L=JSON.parse('{"title":"用 Linux blkid 命令查找块设备详情 | LCTT x X-CMD","titleTemplate":false,"description":"用 Linux blkid 命令查找块设备详情 | LCTT (201501) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"用 Linux blkid 命令查找块设备详情 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"用 Linux blkid 命令查找块设备详情 | LCTT (201501) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201501/20141124 Linux blkid Command to Find Block Devices Details","title":"用 Linux blkid 命令查找块设备详情","tag":"201501","desc":""},"relativePath":"201501/20141124 Linux blkid Command to Find Block Devices Details.md","filePath":"[post].md"}'),b={name:"201501/20141124 Linux blkid Command to Find Block Devices Details.md"};function k(m,l,u,x,g,h){const t=d("Link");return r(),s("div",null,[l[17]||(l[17]=e("h1",{id:"用-linux-blkid-命令查找块设备详情",tabindex:"-1"},[i("用 Linux blkid 命令查找块设备详情 "),e("a",{class:"header-anchor",href:"#用-linux-blkid-命令查找块设备详情","aria-label":"Permalink to “用 Linux blkid 命令查找块设备详情”"},"​")],-1)),l[18]||(l[18]=e("p",null,[i("今天我们将会向你展示如何使用 "),e("strong",null,"lsblk"),i(" 和 "),e("strong",null,"blkid"),i(" 工具来查找关于块设备的信息，我们使用的是一台安装了 CentOS 7.0 的机器。")],-1)),l[19]||(l[19]=e("h2",{id:"lsblk",tabindex:"-1"},[i("lsblk "),e("a",{class:"header-anchor",href:"#lsblk","aria-label":"Permalink to “lsblk”"},"​")],-1)),e("p",null,[l[1]||(l[1]=e("strong",null,"lsblk",-1)),l[2]||(l[2]=i(" 是一个 Linux 工具，它会显示有关你系统里所有可用块设备的信息。它从 ",-1)),n(t,{href:"https://www.kernel.org/doc/Documentation/filesystems/sysfs.txt"},{default:o(()=>[...l[0]||(l[0]=[i("sysfs 文件系统",-1)])]),_:1}),l[3]||(l[3]=i(" 中获取信息。默认情况下，这个工具将会以树状格式显示（除了内存虚拟磁盘外的）所有块设备。",-1))]),l[20]||(l[20]=p(`<h3 id="lsblk-默认输出" tabindex="-1">lsblk 默认输出 <a class="header-anchor" href="#lsblk-默认输出" aria-label="Permalink to “lsblk 默认输出”">​</a></h3><p>默认情况下 lsblk 会将块设备输出为树状格式：</p><ul><li><p><strong>NAME</strong> —— 设备的名称</p></li><li><p><strong>MAJ:MIN</strong> —— Linux 操作系统中的每个设备都以一个文件表示，对块（磁盘）设备来说，这里用主次设备编号来描述设备。</p></li><li><p><strong>RM</strong> —— 可移动设备。如果这是一个可移动设备将显示 1，否则显示 0。</p></li><li><p><strong>TYPE</strong> —— 设备的类型</p></li><li><p><strong>MOUNTPOINT</strong> —— 设备挂载的位置</p></li><li><p><strong>RO</strong> —— 对于只读文件系统，这里会显示 1，否则显示 0。</p></li><li><p><strong>SIZE</strong> —— 设备的容量</p></li></ul><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/10/lsblk.jpg" alt=""></p><h3 id="显示设备的所有者" tabindex="-1">显示设备的所有者 <a class="header-anchor" href="#显示设备的所有者" aria-label="Permalink to “显示设备的所有者”">​</a></h3><p>若想显示设备所有者相关的信息，包括文件的所属用户、所属组以及文件系统挂载的模式，你可以使用 -m 选项，像这样：</p><pre><code>lsblk -m
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/10/lsblk-m.jpg" alt=""></p><h3 id="列出设备块" tabindex="-1">列出设备块 <a class="header-anchor" href="#列出设备块" aria-label="Permalink to “列出设备块”">​</a></h3><p>如果你只想要列出设备，而不想让他们以树状输出，你可以使用 -l 选项：</p><pre><code>lsblk -l
</code></pre><h3 id="在脚本中使用" tabindex="-1">在脚本中使用 <a class="header-anchor" href="#在脚本中使用" aria-label="Permalink to “在脚本中使用”">​</a></h3><p>高级技巧：如果你想要在脚本中使用而希望剔除表头，你可以这样使用 -n 选项：</p><pre><code>lsblk -ln
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/10/lsblk-ln.jpg" alt=""></p><h2 id="blkid" tabindex="-1">blkid <a class="header-anchor" href="#blkid" aria-label="Permalink to “blkid”">​</a></h2><p><strong>blkid</strong> 命令是一个命令行工具，它可以显示关于可用块设备的信息。它可以识别一个块设备内容的类型（如文件系统、交换区）以及从内容的元数据（如卷标或 UUID 字段）中获取属性（如 tokens 和键值对）。它主要有两类作用：用指定的键值对搜索一个设备，或是显示一个或多个设备的键值对。</p><h3 id="blkid-使用方法" tabindex="-1">blkid 使用方法 <a class="header-anchor" href="#blkid-使用方法" aria-label="Permalink to “blkid 使用方法”">​</a></h3><p>不添加任何参数直接运行 blkid 将会输出所有可用的设备、它们的通用唯一识别码（UUID）、文件系统类型以及卷标（如果有设置过）。</p><pre><code># blkid
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/10/blkid.jpg" alt=""></p><h3 id="根据名字或-uuid-列出设备" tabindex="-1">根据名字或 UUID 列出设备 <a class="header-anchor" href="#根据名字或-uuid-列出设备" aria-label="Permalink to “根据名字或 UUID 列出设备”">​</a></h3><p>如果你只想显示一个特定设备的信息，你可以将该设备的名字作为选项添加在 blkid 后面：</p><pre><code># blkid /dev/sda1
</code></pre><p>如果你知道一个设备的 UUID 而想要知道它的设备名，你可以用 -U 选项，像这样：</p><pre><code># blkid -U d3b1dcc2-e3b0-45b0-b703-d6d0d360e524
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/10/blkid-uuid.jpg" alt=""></p><h3 id="详细信息" tabindex="-1">详细信息 <a class="header-anchor" href="#详细信息" aria-label="Permalink to “详细信息”">​</a></h3><p>如果你想要获取更多详细信息，你可以使用 -p 和 -o udev 选项来将它们用整齐的格式显示出来，像这样：</p><pre><code># blkid -po udev /dev/sda1
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/10/blkid-po.jpg" alt=""></p><h3 id="重置缓存" tabindex="-1">重置缓存 <a class="header-anchor" href="#重置缓存" aria-label="Permalink to “重置缓存”">​</a></h3><p>有时候设备列表可能不会更新，如果遇到这种情况你可以使用 -g 选项来清理 blkid 的缓存，从而清除已经不存在的设备。</p><pre><code># blkid -g
</code></pre><hr>`,35)),e("p",null,[l[5]||(l[5]=i("via: ",-1)),n(t,{href:"http://linoxide.com/linux-command/linux-command-lsblk-blkid/"},{default:o(()=>[...l[4]||(l[4]=[i("http://linoxide.com/linux-command/linux-command-lsblk-blkid/",-1)])]),_:1})]),e("p",null,[l[9]||(l[9]=i("作者：",-1)),n(t,{href:"http://linoxide.com/author/adriand/"},{default:o(()=>[...l[6]||(l[6]=[i("Adrian Dinu",-1)])]),_:1}),l[10]||(l[10]=i(" 译者：",-1)),n(t,{href:"https://github.com/felixonmars"},{default:o(()=>[...l[7]||(l[7]=[i("felixonmars",-1)])]),_:1}),l[11]||(l[11]=i(" 校对：",-1)),n(t,{href:"https://github.com/wxy"},{default:o(()=>[...l[8]||(l[8]=[i("wxy",-1)])]),_:1})]),e("p",null,[l[14]||(l[14]=i("本文由 ",-1)),n(t,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...l[12]||(l[12]=[i("LCTT",-1)])]),_:1}),l[15]||(l[15]=i(" 原创翻译，",-1)),n(t,{href:"http://linux.cn/"},{default:o(()=>[...l[13]||(l[13]=[i("Linux中国",-1)])]),_:1}),l[16]||(l[16]=i(" 荣誉推出",-1))])])}const c=a(b,[["render",k]]);export{L as __pageData,c as default};
